import React, { useState, useEffect } from 'react'
import Categ from './components/Categ'
import User from './components/User'
import CategDetails from './components/CategDetails'
import Notification from './components/Notification'
import categService from './services/categs'
import loginService from './services/login'
import userService from './services/users'
import imageService from './services/images'
import MainCategForm from './components/MainCategForm'
import SubCategForm from './components/SubCategForm'
import Togglable from './components/Togglable'
import CategView from './components/CategView'
import Menu from './components/Menu'
import Users from './components/Users'
import { TextField } from '@material-ui/core'
import {
  BrowserRouter as Router,
  Switch, Route, Link
} from 'react-router-dom'
import DefaultImg from './assets/default-img.jpg'
import { DropdownButton, Dropdown } from 'react-bootstrap'

let timeoutID
let subCategDataSet = false

const App = () => {
  const [categs, setCategs] = useState([])
  const [newDescription, setNewDescription] = useState('')
  const [newName, setNewName] = useState('')
  const [newMainCateg, setNewMainCateg] = useState('')
  const [newSubCateg, setNewSubCateg] = useState('')
  const [selectedCateg, setSelectedCateg] = useState('')
  const [selectedSubCateg, setSelectedSubCateg] = useState('')
  const [newImage, setNewImage] = useState({ multerImage: DefaultImg })
  const [message, setMessage] = useState(null)
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [user, setUser] = useState(null)
  const [categToUpdateId, setCategToUpdateId] = useState('')
  const mainCategFormRef = React.createRef()
  const subCategFormRef = React.createRef()
  const editCategFormRef = React.createRef()
  const categRef = React.createRef()
  const [users, setUsers] = useState([])

  useEffect(() => {
    userService.getAll().then(users => {
      setUsers(users)
    })
  }, [])

  useEffect(() => {
    categService.getAll().then(categs =>
      setCategs(categs.sort(function(a,b) {
        return b.stars-a.stars
      })))
  }, [])

  useEffect(() => {
    const loggedUserJSON = window.localStorage.getItem('loggedUser')
    if (loggedUserJSON) {
      const user = JSON.parse(loggedUserJSON)
      setUser(user)
      categService.setToken(user.token)
      imageService.setToken(user.token)
    }
  }, [])

  const handleLogin = async (event) => {
    event.preventDefault()
    console.log('logging in with', username)
    try {
      const user = await loginService.login({
        username, password
      })
      window.localStorage.setItem(
        'loggedUser', JSON.stringify(user)
      )
      categService.setToken(user.token)
      imageService.setToken(user.token)
      setUser(user)
      setUsername('')
      setPassword('')
      const newMessage = {
        type: 'success',
        text: `Welcome, ${username}`
      }
      setMessage(newMessage)
      setTimeout(() => { setMessage(null) }, 4000)
    } catch (exception) {
      const newMessage = {
        type: 'error',
        text: 'Wrong credentials'
      }
      setMessage(newMessage)
      setTimeout(() => { setMessage(null) }, 4000)
    }
  }

  const handleLogout = async (event) => {
    event.preventDefault()
    console.log('logging out with', username)
    window.localStorage.clear()
    setUser(null)
    categService.setToken('')
    imageService.setToken('')
  }

  const getSubCategories = () => {
    let set = new Set()
    categs.forEach(function(c) {
      if (c.categ1 === selectedCateg) {
        set.add(c.categ2)
      }
    })
    let array = Array.from(set)
    return array
  }

  const loginForm = () => (
    <div>
      <h2>Log in to application</h2>
      <form onSubmit={handleLogin}>
        <div>
          <TextField label="username"
            id="username"
            type="text"
            value={username}
            name="Username"
            onChange={({ target }) => setUsername(target.value)}
          />
        </div>
        <div>
          <TextField label="password"
            id="password"
            type="password"
            value={password}
            name="Password"
            onChange={({ target }) => setPassword(target.value)}
          />
        </div>
        <button type="submit" class="btn btn-success" id="login-button">login</button>
      </form>
    </div>
  )

  const mainCategForm = () => {
    if (selectedCateg === '' && categs.length > 0) {
      setSelectedCateg(categs[0].categ1)
    }
    return (
      <Togglable buttonLabel='New category' cancelLabel='Cancel' initializeFields={initializeFields} ref={mainCategFormRef}>
        <MainCategForm
          addMainCateg={addMainCateg}
          newMainCateg={newMainCateg}
          handleMainCategChange={handleMainCategChange}
        />
      </Togglable>
    )
  }

  const subCategForm = () => {
    let subCategories = getSubCategories()
    return (
      <Togglable buttonLabel='New item' cancelLabel='Cancel' initializeFields={initializeFields} ref={subCategFormRef}>
        <SubCategForm
          addSubCateg={addSubCateg}
          newSubCateg={newSubCateg}
          handleSubCategChange={handleSubCategChange}
          newName={newName}
          handleNameChange={handleNameChange}
          newDescription={newDescription}
          handleDescriptionChange={handleDescriptionChange}
          newImage={newImage}
          handleImageChange={handleImageChange}
          selectedSubCateg={selectedSubCateg}
          handleSelectedSubCategChange={handleSelectedSubCategChange}
          subCategories={subCategories}
        />
      </Togglable>
    )
  }

  const setSubCategData = () => {
    if (!subCategDataSet) {
      subCategDataSet = true
      const categToUpdate = categs.find(categ => categ.id === categToUpdateId)
      if (categToUpdate !== undefined) {
        setSelectedSubCateg(categToUpdate.categ2)
        setNewDescription(categToUpdate.description)
        setNewName(categToUpdate.name)
        if (categToUpdate.image) {
          setNewImage({
            multerImage: categToUpdate.image.imageData
          })
        } else {
          setDefaultImage()
        }
      }
    }
  }

  const editCategForm = (id) => {
    let subCategories = getSubCategories()
    setCategToUpdateId(id)
    return (
      <Togglable buttonLabel='Edit' cancelLabel='Cancel' initializeFields={initializeFields} setSubCategData={setSubCategData} ref={editCategFormRef}>
        <SubCategForm
          addSubCateg={editSubCateg}
          newSubCateg={newSubCateg}
          handleSubCategChange={handleSubCategChange}
          newName={newName}
          handleNameChange={handleNameChange}
          newDescription={newDescription}
          handleDescriptionChange={handleDescriptionChange}
          newImage={newImage}
          handleImageChange={handleImageChange}
          selectedSubCateg={selectedSubCateg}
          handleSelectedSubCategChange={handleSelectedSubCategChange}
          subCategories={subCategories}
        />
      </Togglable>
    )
  }

  const initializeFields = () => {
    setSelectedSubCateg('')
    setNewMainCateg('')
    setNewSubCateg('')
    setNewDescription('')
    setNewName('')
    setDefaultImage()
    subCategDataSet = false
  }

  const categDropDown = () => (
    <DropdownButton id="dropdown-basic-button" title={selectedCateg}
      onSelect={e =>
        setSelectedCateg(e)
      }
    >
      {categs.map(categ => (
        categ.isMainCateg === true &&
      <Dropdown.Item eventKey={categ.categ1}>{categ.categ1}</Dropdown.Item>
      ))}
    </DropdownButton>
  )

  const addMainCateg = (event) => {
    event.preventDefault()
    const mainCategObject = {
      categ1: newMainCateg,
      name: '',
      isMainCateg: true,
      id: categs.length + 1,
    }
    mainCategObject.user=user

    categService
      .create(mainCategObject)
      .then(returnedCateg => {
        setCategs(categs.concat(returnedCateg))
        const newMessage = {
          type: 'success',
          text: `New category ${newMainCateg} created`
        }
        setMessage(newMessage)
      }).catch(error => {
        const newMessage = {
          type: 'error',
          text: 'error creating category, name must not be empty'
        }
        setMessage(newMessage)
      })
    mainCategFormRef.current.toggleVisibility()
    setTimeout(() => { setMessage(null) }, 4000)
    if (selectedCateg === '') {
      setSelectedCateg(newMainCateg)
    }
    setNewMainCateg('')
  }

  const addSubCateg = (event) => {
    event.preventDefault()
    const subCateg = newSubCateg === '' ? selectedSubCateg : newSubCateg
    const subCategObject = {
      categ1: selectedCateg,
      categ2: subCateg,
      name: newName,
      description: newDescription,
      isMainCateg: false,
      id: categs.length + 1,
    }
    subCategObject.user=user
    subCategObject.image=newImage.imageObject

    categService
      .create(subCategObject)
      .then(returnedCateg => {
        setCategs(categs.concat(returnedCateg))
        const newMessage = {
          type: 'success',
          text: `New item ${newName} created`
        }
        setMessage(newMessage)
      }).catch(error => {
        const newMessage = {
          type: 'error',
          text: 'error creating item, name must not be empty'
        }
        setMessage(newMessage)
      })
    subCategFormRef.current.toggleVisibility()
    setTimeout(() => { setMessage(null) }, 4000)
    setDefaultImage()
    setNewSubCateg('')
    setSelectedSubCateg('')
    setNewName('')
    setNewDescription('')
  }

  const editSubCateg = (event) => {
    event.preventDefault()
    const subCateg = newSubCateg === '' ? selectedSubCateg : newSubCateg
    const categToUpdate = categs.find(categ => categ.id === categToUpdateId)
    const updatedCateg = {
      stars: categToUpdate.stars,
      categ1: categToUpdate.categ1,
      categ2: subCateg,
      name: newName,
      description: newDescription,
      isMainCateg: false
    }
    updatedCateg.image=newImage.imageObject
    categService.update(categToUpdateId, updatedCateg)
      .then(response => {
        setCategs(categs.map(categ => categ.id !== categToUpdateId ? categ : response))
        const newMessage = {
          type: 'success',
          text: `Category ${updatedCateg.name} updated`
        }
        setMessage(newMessage)
      }).catch(error => {
        const newMessage = {
          type: 'error',
          text: 'error updating item'
        }
        setMessage(newMessage)
      })
    clearTimeout(timeoutID)
    editCategFormRef.current.toggleVisibility()
    timeoutID = setTimeout(() => { setMessage(null) }, 4000)
    setDefaultImage()
    setNewSubCateg('')
    setSelectedSubCateg('')
    setNewName('')
    setNewDescription('')
    setCategToUpdateId('')
    subCategDataSet = false
  }

  const handleDeleteClick = (categ) => {
    console.log('deleting', categ.id)
    const name = categ.name
    if (window.confirm(`Delete category ${name}?`)) {
      deleteCateg(categ)
    }
  }

  const deleteCateg = (categ) => {
    categService.deleteCateg(categ.id)
      .then(response => {
        const updatedCategs = categs.filter(p => p.id !== categ.id)
        setCategs(updatedCategs)
      }).then(e => {
        const newMessage = {
          type: 'success',
          text: `Deleted ${categ.name}`
        }
        setMessage(newMessage)
      }).catch(error => {
        const newMessage = {
          type: 'error',
          text: `${categ.name} has already been removed from the server!`
        }
        setMessage(newMessage)
      })
    setTimeout(() => { setMessage(null) }, 4000)
  }


  const handleMainCategChange = (event) => {
    setNewMainCateg(event.target.value)
  }

  const handleSubCategChange = (event) => {
    setSelectedSubCateg('')
    setNewSubCateg(event.target.value)
  }

  const handleSelectedSubCategChange = (e) => {
    setSelectedSubCateg(e)
    setNewSubCateg('')
  }

  const handleNameChange = (event) => {
    setNewName(event.target.value)
  }

  const handleDescriptionChange = (event) => {
    setNewDescription(event.target.value)
  }

  const handleImageChange = (e) => {
    const imageFormObj = new FormData()

    imageFormObj.append('imageName', 'multer-image-' + Date.now())
    imageFormObj.append('imageData', e.target.files[0])

    const multerImage = URL.createObjectURL(e.target.files[0])
    imageFormObj.append('multerImage', multerImage)

    imageService.create(imageFormObj)
      .then((data) => {
        setNewImage({
          multerImage: multerImage,
          imageObject: { id: data.id, imageData: data.imageData, imageName: data.imageName }
        })
        if (data) {
          alert('Image has been successfully uploaded')
        }
      })
      .catch((err) => {
        alert('Error while uploading image')
        console.log(err)
      })
  }

  const setDefaultImage = () => {
    setNewImage({
      multerImage: DefaultImg
    })
  }

  return (
    <div>
      <Router>
        <Menu user={user} handleLogout={handleLogout} />
        <Notification message={message} />
        <Switch>
          <Route path="/categ/:id" render={({ match }) =>
            <CategView id={match.params.id} categs={categs} initializeFields={initializeFields} editCategForm={editCategForm} />
          }>
          </Route>
          <Route path="/users/:id" render={({ match }) =>
            <User id={match.params.id} users={users}/>
          }>
          </Route>
          <Route path="/users">
            <Users users={users}/>
          </Route>
          <Route path="/">
            {user === null ?
              loginForm() :
              <div>
                <p>{mainCategForm()} {categs.length > 0 && subCategForm()}</p>
                {categDropDown()}
                <br></br>
                <div className="categ">
                  {categs.map(categ =>
                    categ.isMainCateg === false &&
                    categ.categ1 === selectedCateg &&
                    <div className="categ">
                      <Categ key={categ.id} categ={categ} handleDeleteClick={handleDeleteClick} user={user} />
                      <Togglable buttonLabel='View' cancelLabel='Hide' initializeFields={initializeFields} className="view" ref={categRef}>
                        <CategDetails key={categ.id} categ={categ} />
                      </Togglable>
                    </div>
                  )}
                </div>
              </div>
            }
          </Route>
        </Switch>
      </Router>
    </div>
  )
}

export default App