import React from 'react'

const User = ({ id, users }) => {
  const user = users.filter(u => u.id === id)[0]
  let categs = []

  if (user === undefined) {
    return null
  } else {
    categs = user.categs
  }
  return (
    <div>
      <h3>{user.name}</h3>
      <h4>added category items:</h4>
      <ul>
        {categs.map(categ =>
          <li key={categ.id}>{categ.name}</li>)}
      </ul>
    </div>
  )
}

export default User